code_sketch:
opaque type Money = (Long, Currency)               // minor units, currency
object Money:
  def apply(minorUnits: Long, currency: Currency): Money = (minorUnits, currency)
  extension (m: Money)
    def minorUnits: Long = m._1
    def +(other: Money): Either[CurrencyMismatch, Money] =
      if m._2 == other._2 then Right((m._1 + other._1, m._2))
      else Left(CurrencyMismatch(m._2, other._2))

variants.code_sketch:
opaque type Money = (Long, Currency)               // minor units, currency
object Money:
  def apply(minorUnits: Long, currency: Currency): Money = (minorUnits, currency)
  extension (m: Money)
    def minorUnits: Long = m._1
    def +(other: Money): Either[CurrencyMismatch, Money] =
      if m._2 == other._2 then Right((m._1 + other._1, m._2))
      else Left(CurrencyMismatch(m._2, other._2))

final class Money[C <: Currency](val minorUnits: Long) extends AnyVal {
  def +(other: Money[C]): Money[C] = new Money[C](minorUnits + other.minorUnits)
}
